int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;

    vector<int> a(n + 1);
    vector<int> ones;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        if (a[i] == 1) ones.push_back(i);
    }

    long long ans = 0;
    int m = ones.size();
    for (int j = 0; j < m; j++) {
        long long left = ones[j] - (j > 0 ? ones[j - 1] : 0);
        long long right = (j + 1 < m ? ones[j + 1] : n + 1) - ones[j];
        ans += left * right;
    }

    cout << ans << endl;
    return 0;
}
